1	// `roster review <repo> --observational`: fetch → parse → identify → score, then reports/<slug>/.
2	// Every stage is a TOOL span inside one WORKFLOW review span (DESIGN.md §"Observability (neatlogs)"). The
3	// review ends with one line of wall time per stage.
4	import { join, resolve } from "node:path";
5	import type { Command } from "../cli.ts";
6	import { priceSession } from "../price/index.ts";
7	import { flushObs, initObs, setSession, withSpan } from "../obs/index.ts";
8	import { ATTR, summaryAttr } from "../obs/attributes.ts";
9	import { fetchCheckpoints } from "../ingest/fetch.ts";
10	import { type ParsedSession, parseCheckpoints } from "../ingest/parse.ts";
11	import { type Identity, identify, inferenceAccuracy } from "../identity/index.ts";
12	import { survival, survivalMany } from "../score/survival.ts";
13	import { isReverted, reverted } from "../score/revert.ts";
14	import { BUDGET_MESSAGE, gitFailure, gitPool, type GitResult, type GitRunner, rework, reworkShares, trackMany } from "../score/rework.ts";
15	import { buildSetupRows, buildTags, repoSlug, type ReviewReport, slugDir, writeReview } from "../review/export.ts";
16	import type { Outcome, Review, Session } from "../types.ts";
17	
18	export const DEFAULT_CACHE = ".roster/cache";
19	/** Mature = at least this many first-parent commits after the session's commit, and this many seconds older than HEAD. */
20	export const MIN_DEPTH = 5;
21	export const MIN_AGE_S = 6 * 3600;
22	
23	const STAGES = ["fetch", "parse", "identify", "score"] as const;
24	type Stage = (typeof STAGES)[number];
25	
26	const USAGE = `usage: roster review <repo> --observational [--out <dir>] [--cache <dir>]
27	
28	  <repo>            a git URL or a local path to a repo that has Entire checkpoints
29	  --observational   score sessions that already exist (evidence level A). Required for now.
30	  --out <dir>       where to write review.json, review.md, sessions.json and outcomes.json
31	                    (default reports/<slug>)
32	  --cache <dir>     fetch cache (default ${DEFAULT_CACHE})`;
33	
34	export interface ReviewArgs {
35	  repo: string;
36	  out: string | undefined;
37	  cache: string;
38	}
39	
40	/** Thrown for bad arguments. The CLI prints the message and exits 2. */
41	export class UsageError extends Error {}
42	
43	/** Parses the arguments after `review`. Throws UsageError on anything it does not accept. */
44	export function parseReviewArgs(args: string[]): ReviewArgs {
45	  let repo: string | undefined;
46	  let observational = false;
47	  let out: string | undefined;
48	  let cache = DEFAULT_CACHE;
49	  for (let i = 0; i < args.length; i++) {
50	    const a = args[i]!;
51	    const eq = a.indexOf("=");
52	    const name = eq === -1 ? a : a.slice(0, eq);
53	    // A flag takes its value inline (--out=dir) or as the next argument (--out dir).
54	    const takeValue = (): string => {
55	      if (eq !== -1) return a.slice(eq + 1);
56	      const v = args[++i];
57	      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
58	      return v;
59	    };
60	    if (name === "--observational" && eq === -1) observational = true;
61	    else if (name === "--out") out = takeValue();
62	    else if (name === "--cache") cache = takeValue();
63	    else if (a.startsWith("-")) throw new UsageError(`unknown flag ${a}`);
64	    else if (repo === undefined) repo = a;
65	    else throw new UsageError(`unexpected argument ${a}`);
66	  }
67	  if (repo === undefined) throw new UsageError("missing <repo>");
68	  if (!observational) {
69	    throw new UsageError("only --observational is implemented; the controlled replay path is not built yet");
70	  }
71	  return { repo, out, cache };
72	}
73	
74	const NO_DATA =
75	  "no Entire data found. Run `entire enable` in the source repo, push its entire/checkpoints/v1 branch, and try again.";
76	
77	function git(repo: string, args: string[]): string {
78	  const p = Bun.spawnSync(["git", "-c", "core.quotepath=off", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
79	  if (p.exitCode !== 0) throw new Error(`git ${args[0]} failed: ${p.stderr.toString().trim()}`);
80	  return p.stdout.toString();
81	}
82	
83	/** Wall time the whole scoring pass may take before the remaining sessions are marked not scored. */
84	export const SCORE_BUDGET_MS = 120_000;
85	const PROGRESS_EVERY = 10;
86	
87	export interface ScoreOptions {
88	  budgetMs?: number;
89	  /** Called with a line like `score: 10/50 sessions, 12.3 s` at every 10th session. */
90	  onProgress?: (line: string) => void;
91	}
92	
93	interface ScoreContext {
94	  repo: string;
95	  head: string;
96	  headTime: number;
97	}
98	
99	/** One user prompt means nobody steered the session. Needs no commit age; null when the count is unknown. */
100	const isUnattended = (s: ParsedSession): boolean | null => (Number.isFinite(s.n_user_prompts) ? s.n_user_prompts === 1 : null);
101	
102	const tooYoung = (session_id: string, unattended: boolean | null = null): Outcome => ({
103	  session_id,
104	  status: "too_young",
105	  survival: null,
106	  reverted: null,
107	  rework_human: null,
108	  rework_agent: null,
109	  unattended,
110	  tests_at_commit: null,
111	  difficulty: null,
112	  tercile: null,
113	});
114	
115	/**
116	 * Scores one session from its commit. Sessions without a trailer-linked commit, and commits that are not yet
117	 * mature, come back too_young with null metrics. Throws when git cannot read the commit.
118	 */
119	export function scoreSession(session: ParsedSession, ctx: ScoreContext): Outcome {
120	  const sha = session.commit_sha;
121	  if (sha === null) return tooYoung(session.id, isUnattended(session));
122	  const depth = Number(git(ctx.repo, ["rev-list", "--count", "--first-parent", `${sha}..${ctx.head}`]).trim());
123	  const age = ctx.headTime - Number(git(ctx.repo, ["show", "-s", "--format=%ct", sha]).trim());
124	  if (depth < MIN_DEPTH || age < MIN_AGE_S) return tooYoung(session.id, isUnattended(session));
125	
126	  const surv = survival(ctx.repo, [sha], ctx.head);
127	  const rw = rework(ctx.repo, sha);
128	  return {
129	    session_id: session.id,
130	    status: "mature",
131	    survival: surv.ratio,
132	    reverted: reverted(ctx.repo, sha),
133	    rework_human: rw.human,
134	    rework_agent: rw.agent,
135	    unattended: isUnattended(session),
136	    tests_at_commit: null,
137	    difficulty: null,
138	    tercile: null,
139	  };
140	}
141	
142	/**
143	 * scoreSession for every session at once, with the same outcomes. Git work goes through `run` (a pool
144	 * of GIT_PARALLEL processes by default): blame runs once per (file, HEAD) and rework and reverts share
145	 * one history pass. Each entry is the session's Outcome, or the Error that stopped it.
146	 */
147	export async function scoreAll(
148	  sessions: ParsedSession[],
149	  ctx: ScoreContext,
150	  inner: GitRunner = gitPool(),
151	  opts: ScoreOptions = {},
152	): Promise<(Outcome | Error)[]> {
153	  const started = performance.now();
154	  const budgetMs = opts.budgetMs ?? SCORE_BUDGET_MS;
155	  // Past the budget every git call is refused, so the sessions still waiting come back not scored.
156	  const run: GitRunner = (repo, args, stdin) => {
157	    const left = budgetMs - (performance.now() - started);
158	    const refused: GitResult = { ok: false, out: "", err: BUDGET_MESSAGE, budget: true };
159	    if (left <= 0) return Promise.resolve(refused);
160	    let timer: ReturnType<typeof setTimeout>;
161	    const expired = new Promise<GitResult>((done) => (timer = setTimeout(() => done(refused), left)));
162	    return Promise.race([inner(repo, args, stdin), expired]).finally(() => clearTimeout(timer));
163	  };
164	  const out = async (args: string[]) => {
165	    const r = await run(ctx.repo, ["-c", "core.quotepath=off", ...args]);
166	    if (!r.ok) throw gitFailure(r, `git ${args[0]}`);
167	    return r.out;
168	  };
169	  const asError = (err: unknown) => (err instanceof Error ? err : new Error(String(err)));
170	
171	  // Maturity: the same two questions scoreSession asks, all sessions in parallel.
172	  const maturity = await Promise.all(
173	    sessions.map(async (s): Promise<string | null | Outcome | Error> => {
174	      const sha = s.commit_sha;
175	      if (sha === null) return tooYoung(s.id, isUnattended(s));
176	      const [depthR, showR] = await Promise.allSettled([
177	        out(["rev-list", "--count", "--first-parent", `${sha}..${ctx.head}`]),
178	        out(["show", "-s", "--format=%H %ct", sha]),
179	      ]);
180	      if (depthR.status === "rejected") return asError(depthR.reason);
181	      if (showR.status === "rejected") return asError(showR.reason);
182	      const [full = "", time = ""] = showR.value.trim().split(" ");
183	      const depth = Number(depthR.value.trim());
184	      if (depth < MIN_DEPTH || ctx.headTime - Number(time) < MIN_AGE_S) return tooYoung(s.id, isUnattended(s));
185	      return full;
186	    }),
187	  );
188	
189	  const mature = [...new Set(maturity.filter((m): m is string => typeof m === "string"))];
190	  let head: string | Error;
191	  try {
192	    head = (await out(["rev-parse", "--verify", `${ctx.head}^{commit}`])).trim();
193	  } catch {
194	    head = new Error(`cannot resolve ${ctx.head} in ${ctx.repo}`);
195	  }
196	  // Progress counts sessions: those already settled (too young, no commit, failed) plus each mature
197	  // commit's sessions as its survival lands. A line goes out at every 10th.
198	  const sessionsOf = new Map<string, number>();
199	  maturity.forEach((m) => typeof m === "string" && sessionsOf.set(m, (sessionsOf.get(m) ?? 0) + 1));
200	  let done = sessions.length - [...sessionsOf.values()].reduce((a, b) => a + b, 0);
201	  let reported = 0;
202	  const advance = (n: number) => {
203	    done += n;
204	    for (; (reported + 1) * PROGRESS_EVERY <= done; reported++) {
205	      const secs = ((performance.now() - started) / 1000).toFixed(1);
206	      opts.onProgress?.(`score: ${(reported + 1) * PROGRESS_EVERY}/${sessions.length} sessions, ${secs} s`);
207	    }
208	  };
209	  advance(0);
210	  const failAll = (err: unknown) => new Map(mature.map((sha) => [sha, asError(err)] as const));
211	  const [surv, tracked] = await Promise.all([
212	    typeof head === "string"
213	      ? survivalMany(ctx.repo, mature.map((sha) => [sha]), head, run, new Map(), (i) => advance(sessionsOf.get(mature[i]!) ?? 0))
214	      : mature.map(() => head as Error),
215	    trackMany(ctx.repo, mature, run).catch(failAll),
216	  ]);
217	  const survOf = new Map(mature.map((sha, i) => [sha, surv[i]!]));
218	
219	  return sessions.map((s, i) => {
220	    const m = maturity[i]!;
221	    if (typeof m !== "string") return m;
222	    const sv = survOf.get(m)!;
223	    if (sv instanceof Error) return sv;
224	    const t = tracked.get(m) ?? new Error(`no history for ${m}`);
225	    if (t instanceof Error) return t;
226	    const rw = reworkShares(t);
227	    return {
228	      session_id: s.id,
229	      status: "mature",
230	      survival: sv.ratio,
231	      reverted: isReverted(t),
232	      rework_human: rw.human,
233	      rework_agent: rw.agent,
234	      unattended: isUnattended(s),
235	      tests_at_commit: null,
236	      difficulty: null,
237	      tercile: null,
238	    };
239	  });
240	}
241	
242	const pct = (x: number) => `${(100 * x).toFixed(1)}%`;
243	
244	/** Wall time per stage, in ms. */
245	type Timings = Map<string, number>;
246	
247	/** Timed stages in print order. `difficulty` is not part of this command yet, so it prints as not run. */
248	const TIMED = ["fetch", "parse", "identify", "score", "difficulty", "export"] as const;
249	
250	export function formatTimings(times: Timings, totalMs: number): string {
251	  const s = (ms: number) => `${(ms / 1000).toFixed(2)}s`;
252	  const parts = TIMED.map((name) => {
253	    const ms = times.get(name);
254	    return `${name} ${ms === undefined ? "not run" : s(ms)}`;
255	  });
256	  return `time: ${parts.join(" · ")} · total ${s(totalMs)}`;
257	}
258	
259	async function timed<T>(times: Timings, name: string, work: () => Promise<T>): Promise<T> {
260	  const t0 = performance.now();
261	  try {
262	    return await work();
263	  } finally {
264	    times.set(name, performance.now() - t0);
265	  }
266	}
267	
268	async function stage<T>(times: Timings, n: number, name: Stage, repo: string, work: () => Promise<[T, string]>): Promise<T> {
269	  return timed(times, name, () =>
270	    withSpan("TOOL", name, { repo }, async () => {
271	      const [value, detail] = await work();
272	      console.log(`[${n}/${STAGES.length}] ${name}: ${detail}`);
273	      return value;
274	    }),
275	  );
276	}
277	
278	/** Runs the whole review. Resolves to the exit code; writes reports only when every stage succeeds. */
279	export async function runReview(args: ReviewArgs): Promise<number> {
280	  const label = repoSlug(args.repo);
281	  const outDir = resolve(args.out ?? join("reports", slugDir(label)));
282	  const createdAt = new Date().toISOString();
283	  const reviewId = `${slugDir(label)}-${createdAt.replace(/\D/g, "").slice(0, 14)}`;
284	
285	  await initObs({ workflowName: "roster-review" });
286	  setSession(reviewId);
287	  console.log(`roster review ${label} (${reviewId}) → ${outDir}`);
288	  const times: Timings = new Map();
289	  const t0 = performance.now();
290	  try {
291	    // One span per stage, never one per session: session-level detail goes into one roster.summary count line.
292	    return await withSpan("WORKFLOW", "review", { repo: label }, async (root) => {
293	      const fetched = await stage(times, 1, "fetch", label, async () => {
294	        const f = await fetchCheckpoints(args.repo, { cacheDir: resolve(args.cache) });
295	        return [f, `backend=${f.backend} head=${f.headSha.slice(0, 12) || "none"}`];
296	      });
297	      if (fetched.backend === "none") {
298	        console.error(`roster review: ${NO_DATA}`);
299	        return 1;
300	      }
301	      if (fetched.headSha === "") {
302	        console.error("roster review: the repo has checkpoints but no HEAD commit to score them against");
303	        return 1;
304	      }
305	
306	      const sessions = await stage(times, 2, "parse", label, async () => {
307	        const parsed = parseCheckpoints(fetched.repoPath, fetched.backend === "refs" ? "git-refs" : "branch");
308	        return [parsed, `${parsed.length} sessions`];
309	      });
310	
311	      const identities: Identity[] = await stage(times, 3, "identify", label, async () => {
312	        const ids = sessions.map((s) => identify(s, fetched.repoPath));
313	        const setups = new Set(ids.map((i) => i.setupId).filter((x): x is string => x !== null)).size;
314	        const acc = inferenceAccuracy(ids);
315	        return [ids, `${setups} setups, tag accuracy ${acc === null ? "n/a (no tagged sessions)" : pct(acc)}`];
316	      });
317	
318	      const headTime = Number(git(fetched.repoPath, ["show", "-s", "--format=%ct", fetched.headSha]).trim());
319	      const ctx: ScoreContext = { repo: fetched.repoPath, head: fetched.headSha, headTime };
320	      const scored = await stage(times, 4, "score", label, async () => {
321	        const out: Session[] = [];
322	        const outcomes: Outcome[] = [];
323	        const failed: string[] = [];
324	        const scoredAll = await scoreAll(sessions, ctx, undefined, { onProgress: (l) => console.log(l) });
325	        sessions.forEach((s, i) => {
326	          const id = identities[i]!;
327	          const cost = priceSession(s.model, {
328	            input: s.tokens_in,
329	            output: s.tokens_out,
330	            cache_read: s.cache_read,
331	            cache_write: s.cache_write,
332	          }).usd;
333	          out.push({ ...stripParsed(s), setup_id: id.setupId, cost_usd: cost });
334	          const o = scoredAll[i]!;
335	          if (o instanceof Error) {
336	            failed.push(`${s.id}: ${o.message}`);
337	            outcomes.push(tooYoung(s.id, isUnattended(s)));
338	          } else outcomes.push(o);
339	        });
340	        const mature = outcomes.filter((o) => o.status === "mature").length;
341	        return [
342	          { out, outcomes, failed },
343	          `${mature} mature, ${outcomes.length - mature} too young${failed.length ? `, ${failed.length} failed` : ""}`,
344	        ];
345	      });
346	
347	      root.setAttribute(
348	        ATTR.summary,
349	        summaryAttr({
350	          sessions: sessions.length,
351	          mature: scored.outcomes.filter((o) => o.status === "mature").length,
352	          too_young: scored.outcomes.filter((o) => o.status === "too_young").length,
353	          failed: scored.failed.length,
354	          setups: new Set(identities.map((i) => i.setupId).filter((x) => x !== null)).size,
355	          unpriced: scored.out.filter((s) => s.cost_usd === null).length,
356	        }),
357	      );
358	
359	      const notes = [
360	        `${scored.outcomes.filter((o) => o.status === "too_young").length} sessions are too young or have no commit: a session is mature at ≥ ${MIN_DEPTH} first-parent commits and ≥ ${MIN_AGE_S / 3600} h before HEAD`,
361	        ...scored.failed.map((f) => `could not be scored: ${f}`),
362	        `${scored.out.filter((s) => s.cost_usd === null).length} sessions have no price (unknown model, or a price that depends on prompt size)`,
363	        `${scored.out.filter((s) => s.setup_id === null).length} sessions have no setup because their rules hash is unknown`,
364	      ];
365	      const tags = buildTags(scored.out);
366	      const review: Review = {
367	        id: reviewId,
368	        repo: label,
369	        created_at: createdAt,
370	        generated_at: createdAt,
371	        has_entire_data: true,
372	        setups: buildSetupRows(scored.out, scored.outcomes),
373	        ...(tags ? { tags } : {}),
374	        label: "insufficient_data",
375	        suspect: null,
376	        odds_ratio: null,
377	        ci95: null,
378	        p_value: null,
379	        evidence_level: "A",
380	      };
381	      const report: ReviewReport = {
382	        review,
383	        note:
384	          "No suspect call. The difficulty-matched Mantel–Haenszel test (DESIGN.md §\"Difficulty and review\") is not part of this command yet, so the setup numbers below are descriptive only.",
385	        sessions: scored.out,
386	        outcomes: scored.outcomes,
387	        notes,
388	      };
389	      const written = await timed(times, "export", async () => writeReview(outDir, report));
390	      console.log(`wrote ${written.join(", ")}`);
391	      console.log(`label ${review.label} · evidence level ${review.evidence_level}`);
392	      return 0;
393	    });
394	  } finally {
395	    if (times.size > 0) console.log(formatTimings(times, performance.now() - t0));
396	    await flushObs();
397	  }
398	}
399	
400	/** A ParsedSession without the parse-only fields, so sessions.json holds Session rows. */
401	function stripParsed(s: ParsedSession): Session {
402	  const { usage_source: _usage, model_source: _model, ...session } = s;
403	  return session;
404	}
405	
406	export const reviewCommand: Command = {
407	  name: "review",
408	  summary: "score a repo's agent sessions (--observational)",
409	  usage: USAGE,
410	  async run(args) {
411	    let parsed: ReviewArgs;
412	    try {
413	      parsed = parseReviewArgs(args);
414	    } catch (err) {
415	      if (!(err instanceof UsageError)) throw err;
416	      console.error(`roster review: ${err.message}\n\n${USAGE}`);
417	      return 2;
418	    }
419	    return runReview(parsed);
420	  },
421	};
