1	// Per-session difficulty (DESIGN.md §"Difficulty and review"): the mean z-score, over the sessions
2	// being compared, of log(1 + lines changed), files touched, graph impact size and first-prompt
3	// length. Terciles split the sessions by that score so setups are compared like for like.
4	
5	import type { Session, Tercile } from "../types.ts";
6	import { gitPool, type GitRunner } from "../score/rework.ts";
7	import { GraphQueue, impactSize, impactSizes, type GraphOptions, type ImpactFallback, type ImpactMethod } from "./graph.ts";
8	
9	export type { ImpactFallback, ImpactMethod } from "./graph.ts";
10	
11	export interface DifficultyFeatures {
12	  /** Added + deleted lines in the session's commit; null when the session has no commit. */
13	  lines_changed: number | null;
14	  files_touched: number;
15	  impact: number;
16	  /** Which impact method produced `impact`. */
17	  impact_method: ImpactMethod;
18	  /** Set by reviewDifficulty: why the graph was asked but fan-in used (null when it was not). */
19	  impact_fallback?: ImpactFallback | null;
20	  first_prompt_len: number;
21	}
22	
23	export interface DifficultyScore {
24	  session_id: string;
25	  features: DifficultyFeatures;
26	  difficulty: number;
27	  tercile: Tercile;
28	}
29	
30	function git(repo: string, args: string[]): { ok: boolean; out: string } {
31	  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
32	  return { ok: p.exitCode === 0, out: p.stdout.toString() };
33	}
34	
35	/** Lines and files changed by `sha` (binary files count as one file, zero lines). */
36	export function commitChange(repo: string, sha: string): { lines: number; files: string[] } | null {
37	  return parseNumstat(git(repo, [...NUMSTAT, sha]));
38	}
39	
40	const NUMSTAT = ["show", "--numstat", "--format=", "--no-renames"];
41	
42	function parseNumstat(r: { ok: boolean; out: string }): { lines: number; files: string[] } | null {
43	  if (!r.ok) return null;
44	  let lines = 0;
45	  const files: string[] = [];
46	  for (const row of r.out.split("\n")) {
47	    const [add, del, path] = row.split("\t");
48	    if (path === undefined) continue;
49	    files.push(path);
50	    lines += (Number(add) || 0) + (Number(del) || 0);
51	  }
52	  return { lines, files };
53	}
54	
55	/** Raw difficulty features of one session. */
56	export function features(session: Session, repo: string, opts: GraphOptions = {}): DifficultyFeatures {
57	  const change = session.commit_sha ? commitChange(repo, session.commit_sha) : null;
58	  const files = session.files.length > 0 ? session.files : change?.files ?? [];
59	  const impact = impactSize(repo, change ? session.commit_sha : null, files, opts);
60	  return {
61	    lines_changed: change?.lines ?? null,
62	    files_touched: files.length,
63	    impact: impact.size,
64	    impact_method: impact.method,
65	    first_prompt_len: session.first_prompt.length,
66	  };
67	}
68	
69	/** z-scores of `xs`; missing values and zero-variance columns score 0 (the mean). */
70	export function zScores(xs: (number | null)[]): number[] {
71	  const present = xs.filter((x): x is number => x !== null);
72	  if (present.length === 0) return xs.map(() => 0);
73	  const mean = present.reduce((s, x) => s + x, 0) / present.length;
74	  const sd = Math.sqrt(present.reduce((s, x) => s + (x - mean) ** 2, 0) / present.length);
75	  return xs.map((x) => (x === null || sd === 0 ? 0 : (x - mean) / sd));
76	}
77	
78	/** Mean z-score of the four features, per row, relative to all rows given. */
79	export function difficultyFromFeatures(rows: DifficultyFeatures[]): number[] {
80	  const cols = [
81	    zScores(rows.map((f) => (f.lines_changed === null ? null : Math.log1p(f.lines_changed)))),
82	    zScores(rows.map((f) => f.files_touched)),
83	    zScores(rows.map((f) => f.impact)),
84	    zScores(rows.map((f) => f.first_prompt_len)),
85	  ];
86	  return rows.map((_, i) => cols.reduce((s, c) => s + c[i]!, 0) / cols.length);
87	}
88	
89	/**
90	 * Terciles by rank: the lowest third of scores is 1, the highest third 3. Ties break by id so the
91	 * split is deterministic.
92	 */
93	export function terciles<T extends { session_id: string; difficulty: number }>(rows: T[]): Map<string, Tercile> {
94	  const sorted = [...rows].sort(
95	    (a, b) => a.difficulty - b.difficulty || (a.session_id < b.session_id ? -1 : a.session_id > b.session_id ? 1 : 0),
96	  );
97	  const out = new Map<string, Tercile>();
98	  sorted.forEach((r, i) => out.set(r.session_id, (Math.floor((3 * i) / sorted.length) + 1) as Tercile));
99	  return out;
100	}
101	
102	/** Difficulty and tercile of every session, scored against the others in `sessions`. */
103	export function difficulty(sessions: Session[], repo: string, opts: GraphOptions = {}): DifficultyScore[] {
104	  return scoreFeatures(sessions, sessions.map((s) => features(s, repo, opts)));
105	}
106	
107	export interface ReviewDifficultyOptions extends GraphOptions {
108	  /** Git runner; default a pool of GIT_PARALLEL processes. */
109	  run?: GitRunner;
110	  /** Concurrent graph calls; default GRAPH_PARALLEL. */
111	  concurrency?: number;
112	}
113	
114	/**
115	 * `difficulty` for a whole review, with bounded graph calls: at most one per touched file in the
116	 * review, GRAPH_PARALLEL at once, REVIEW_TIMEOUT_MS each, every symbol asked once. A session whose
117	 * graph call times out, fails or exceeds the budget uses fan-in, and `impact_fallback` says why.
118	 */
119	export async function reviewDifficulty(
120	  sessions: Session[],
121	  repo: string,
122	  opts: ReviewDifficultyOptions = {},
123	): Promise<{ scores: DifficultyScore[]; queue: GraphQueue }> {
124	  const run = opts.run ?? gitPool();
125	  const changes = await Promise.all(
126	    sessions.map(async (s) => (s.commit_sha ? parseNumstat(await run(repo, [...NUMSTAT, s.commit_sha])) : null)),
127	  );
128	  const touched = sessions.map((s, i) => (s.files.length > 0 ? s.files : changes[i]?.files ?? []));
129	  const queue = new GraphQueue(repo, { ...opts, maxCalls: new Set(touched.flat()).size });
130	  const impacts = await impactSizes(
131	    queue,
132	    run,
133	    sessions.map((s, i) => ({ sha: changes[i] ? s.commit_sha : null, files: touched[i]! })),
134	    opts.maxSymbols,
135	  );
136	  const feats = sessions.map(
137	    (s, i): DifficultyFeatures => ({
138	      lines_changed: changes[i]?.lines ?? null,
139	      files_touched: touched[i]!.length,
140	      impact: impacts[i]!.size,
141	      impact_method: impacts[i]!.method,
142	      impact_fallback: impacts[i]!.fallback,
143	      first_prompt_len: s.first_prompt.length,
144	    }),
145	  );
146	  return { scores: scoreFeatures(sessions, feats), queue };
147	}
148	
149	function scoreFeatures(sessions: Session[], feats: DifficultyFeatures[]): DifficultyScore[] {
150	  const scores = difficultyFromFeatures(feats);
151	  const rows = sessions.map((s, i) => ({ session_id: s.id, features: feats[i]!, difficulty: scores[i]! }));
152	  const t = terciles(rows);
153	  return rows.map((r) => ({ ...r, tercile: t.get(r.session_id)! }));
154	}
155

1	// Names a suspect setup only when a difficulty-matched (tercile-stratified) comparison supports it.
2	// See docs/DESIGN.md §"Difficulty and review". The wording fields are the only labels the design allows.
3	import type { Outcome, Tercile } from "../types.ts";
4	import { mantelHaenszel, type MantelHaenszel, type Stratum } from "./stats.ts";
5	
6	export const SUSPECT_LABEL = "suspect (level A, observational)";
7	export const NO_SUSPECT_LABEL = "no suspect";
8	export const INSUFFICIENT_LABEL = "insufficient data";
9	
10	export const MIN_MATURE_SESSIONS = 8;
11	export const REWORK_BAD_THRESHOLD = 0.3;
12	const ALPHA = 0.05;
13	
14	/** An outcome joined to the setup that produced its session (Outcome itself carries no setup id). */
15	export type SetupOutcome = Outcome & { setup_id: string | null };
16	
17	export interface SuspectResult {
18	  setupId: string | null;
19	  or: number | null;
20	  ci95: [number, number] | null;
21	  p: number | null;
22	  /** Mature sessions of the reported setup. */
23	  n: number;
24	  label: typeof SUSPECT_LABEL | typeof NO_SUSPECT_LABEL | typeof INSUFFICIENT_LABEL;
25	  reason: string;
26	  /** Unmatched comparison (one pooled stratum) for the reported setup, for contrast only. Never used to flag. */
27	  raw: MantelHaenszel | null;
28	}
29	
30	export const isBad = (o: Outcome): boolean => o.reverted === true || (o.rework_human ?? 0) > REWORK_BAD_THRESHOLD;
31	
32	function strataFor(rows: SetupOutcome[], setupId: string): Stratum[] {
33	  const by = new Map<Tercile, Stratum>();
34	  for (const o of rows) {
35	    const t = o.tercile as Tercile;
36	    const s = by.get(t) ?? { a: 0, b: 0, c: 0, d: 0 };
37	    const bad = isBad(o);
38	    if (o.setup_id === setupId) {
39	      if (bad) s.a++;
40	      else s.b++;
41	    } else if (bad) s.c++;
42	    else s.d++;
43	    by.set(t, s);
44	  }
45	  return [...by.values()];
46	}
47	
48	function collapse(strata: Stratum[]): Stratum {
49	  return strata.reduce((t, s) => ({ a: t.a + s.a, b: t.b + s.b, c: t.c + s.c, d: t.d + s.d }), { a: 0, b: 0, c: 0, d: 0 });
50	}
51	
52	export function suspect(outcomes: SetupOutcome[]): SuspectResult {
53	  const rows = outcomes.filter((o) => o.status === "mature" && o.tercile !== null && o.setup_id !== null);
54	  const counts = new Map<string, number>();
55	  for (const o of rows) counts.set(o.setup_id!, (counts.get(o.setup_id!) ?? 0) + 1);
56	  const eligible = [...counts]
57	    .filter(([, n]) => n >= MIN_MATURE_SESSIONS)
58	    .map(([id]) => id)
59	    .sort();
60	
61	  if (eligible.length === 0) {
62	    return {
63	      setupId: null, or: null, ci95: null, p: null, n: 0, label: INSUFFICIENT_LABEL, raw: null,
64	      reason: `no setup has ≥ ${MIN_MATURE_SESSIONS} mature sessions`,
65	    };
66	  }
67	
68	  const results = eligible.map((id) => {
69	    const strata = strataFor(rows, id);
70	    return { id, n: counts.get(id)!, mh: mantelHaenszel(strata), raw: mantelHaenszel([collapse(strata)]) };
71	  });
72	  const flagged = results.filter((r) => r.mh.or > 1 && r.mh.ci95[0] > 1 && r.mh.p < ALPHA);
73	  if (flagged.length > 0) {
74	    const best = flagged.sort((x, y) => x.mh.p - y.mh.p || x.id.localeCompare(y.id))[0]!;
75	    return {
76	      setupId: best.id, or: best.mh.or, ci95: best.mh.ci95, p: best.mh.p, n: best.n, label: SUSPECT_LABEL, raw: best.raw,
77	      reason: `difficulty-matched odds ratio ${best.mh.or.toFixed(2)} (p ${best.mh.p.toFixed(4)}) for ${best.id} vs the rest`,
78	    };
79	  }
80	  // Report the highest matched OR as context; the setup is not named.
81	  const top = results.sort((x, y) => y.mh.or - x.mh.or || x.id.localeCompare(y.id))[0]!;
82	  return {
83	    setupId: null, or: top.mh.or, ci95: top.mh.ci95, p: top.mh.p, n: top.n, label: NO_SUSPECT_LABEL, raw: top.raw,
84	    reason: `no setup with ≥ ${MIN_MATURE_SESSIONS} mature sessions has a difficulty-matched odds ratio above 1 at p < ${ALPHA}`,
85	  };
86	}
87

import { afterAll, beforeAll, describe, expect, test } from "bun:test";
